import React, { useMemo } from "react";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid
} from "recharts";

function InsightsPage({
  transactions,
  alerts,
  insights,
  metrics,
  visuals,
  darkMode,
  goBack
}) {
    // ✅ Build chart data from transactions
const categoryTotals = {};

transactions.forEach((t) => {
  const cat = (t.category || "other").toLowerCase();
  const amount = Number(t.amount || 0);

  categoryTotals[cat] = (categoryTotals[cat] || 0) + amount;
});

// convert to recharts format
const data = Object.keys(categoryTotals).map((key) => ({
  name: key,
  value: categoryTotals[key]
}));

  const COLORS = ["#4f6df5", "#22c55e", "#f59e0b", "#ef4444", "#8b5cf6"];

  // ✅ NEED vs WANT ANALYTICS
const needWantTotals = {
  Need: 0,
  Want: 0
};

transactions.forEach((txn) => {

  const type =
    txn.need_or_want ||
    txn.classify ||
    txn.need_want ||
    txn.need_vs_want ||
    "";

  const amount = Number(txn.amount || 0);

  if (type.toLowerCase() === "need") {
    needWantTotals.Need += amount;
  }

  if (type.toLowerCase() === "want") {
    needWantTotals.Want += amount;
  }
});

// PIE DATA
const needWantData = [
  {
    name: "Needs",
    value: needWantTotals.Need
  },
  {
    name: "Wants",
    value: needWantTotals.Want
  }
];

// TOTAL
const totalNeedWant =
  needWantTotals.Need + needWantTotals.Want;

// PERCENTAGES
const needPercent = totalNeedWant
  ? ((needWantTotals.Need / totalNeedWant) * 100).toFixed(1)
  : 0;

const wantPercent = totalNeedWant
  ? ((needWantTotals.Want / totalNeedWant) * 100).toFixed(1)
  : 0;

// DISCIPLINE SCORE
let disciplineScore = 100;

if (wantPercent > 60) {
  disciplineScore -= 40;
} else if (wantPercent > 40) {
  disciplineScore -= 25;
} else if (wantPercent > 25) {
  disciplineScore -= 10;
}

const exceededAlerts = alerts.filter(
  (a) => a.exceeded
).length;

disciplineScore -= exceededAlerts * 10;

if (disciplineScore < 0) {
  disciplineScore = 0;
}

// MONTHLY TREND
const monthlyTrendMap = {};

transactions.forEach((txn) => {

  if (!txn.date) return;

  const month = txn.date.slice(0, 7);

  const type =
    txn.need_or_want ||
    txn.classify ||
    txn.need_want ||
    txn.need_vs_want ||
    "";

  if (!monthlyTrendMap[month]) {
    monthlyTrendMap[month] = {
      month,
      Need: 0,
      Want: 0
    };
  }

  if (type.toLowerCase() === "need") {
    monthlyTrendMap[month].Need += Number(txn.amount || 0);
  }

  if (type.toLowerCase() === "want") {
    monthlyTrendMap[month].Want += Number(txn.amount || 0);
  }
});

const monthlyNeedWantData =
  Object.values(monthlyTrendMap);

// COLORS
const NEED_WANT_COLORS = [
  "#22c55e",
  "#ef4444"
];

  // 📊 Category Data
const categoryData =
  visuals?.expense_by_category?.map((item) => ({
    name: item.category,
    value: item.amount
  })) || [];

  // 💰 Total Spend
  const totalSpend = useMemo(() => {
    return transactions.reduce((sum, t) => sum + Number(t.amount || 0), 0);
  }, [transactions]);

  // ✅ DAILY BURN RATE
const dailyBurnRate = transactions.length
  ? (totalSpend / 30).toFixed(0)
  : 0;

// ✅ SAVINGS POTENTIAL
const savingsPotential =
  wantPercent > 40
    ? Math.round((needWantTotals.Want * 0.3))
    : Math.round((needWantTotals.Want * 0.15));

// ✅ RISK LEVEL
let riskLevel = "Low";

if (wantPercent > 50 || exceededAlerts >= 2) {
  riskLevel = "High";
} else if (wantPercent > 30 || exceededAlerts >= 1) {
  riskLevel = "Medium";
}

// ✅ SPENDING STYLE
let spendingStyle = "Balanced";

if (wantPercent > 60) {
  spendingStyle = "Impulsive";
} else if (needPercent > 75) {
  spendingStyle = "Highly Disciplined";
} else if (wantPercent > 40) {
  spendingStyle = "Lifestyle Focused";
}

// ✅ FINANCIAL HEALTH
let financialHealth = "Excellent";

if (disciplineScore < 50) {
  financialHealth = "Critical";
} else if (disciplineScore < 70) {
  financialHealth = "Average";
} else if (disciplineScore < 85) {
  financialHealth = "Good";
}

  // 🔝 Top Category
  const topCategory = useMemo(() => {
    if (!categoryData.length) return null;
    return [...categoryData].sort((a, b) => b.value - a.value)[0];
  }, [categoryData]);

  // 🧠 AI Summary
  const aiSummary = useMemo(() => {
    if (!transactions.length) return "Upload a statement to see insights.";

    const alertMsg = alerts.find(a => a.exceeded)
      ? "Some of your budgets have been exceeded."
      : "You are mostly within your budget limits.";

    return `You spent a total of ₹${totalSpend.toFixed(0)} during this period. 
Your highest spending category was ${topCategory?.name}, indicating a key expense driver. 
${alertMsg} Your spending behavior suggests ${
      insights.length > 3 ? "diverse financial activity" : "disciplined spending"
    }.`;
  }, [transactions, alerts, insights, totalSpend, topCategory]);

  return (
    <div className="container" style={{ marginTop: "20px" }}>

      {/* HEADER */}
      <div className="card" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <h2>AI Financial Insights</h2>
          <p style={{ fontSize: "13px", color: "#6b7280" }}>
            Smart analysis of your spending behavior
          </p>
        </div>

        <button
          onClick={goBack}
          style={{
            padding: "6px 14px",
            borderRadius: "8px",
            border: "none",
            background: "#4f6df5",
            color: "#fff",
            cursor: "pointer"
          }}
        >
          ← Back
        </button>
      </div>

      
   {/* KPI CARDS */}
<div
  style={{
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
    columnGap: "20px",
    rowGap: "32px",
    marginTop: "20px",
    alignItems: "stretch"
  }}
>

  {/* TOTAL SPEND */}
  <div className="card">
    <h4>Total Spend</h4>

    <p style={{ fontSize: "20px", fontWeight: "600" }}>
      ₹{totalSpend.toFixed(0)}
    </p>
  </div>

  {/* TOP CATEGORY */}
  <div className="card">
    <h4>Top Category</h4>

    <p style={{ fontSize: "18px", fontWeight: "600" }}>
      {topCategory?.name || "-"}
    </p>
  </div>

  {/* TRANSACTIONS */}
  <div className="card">
    <h4>Transactions</h4>

    <p style={{ fontSize: "18px", fontWeight: "600" }}>
      {transactions.length}
    </p>
  </div>

  {/* DISCIPLINE SCORE */}
  <div className="card">
    <h4>Discipline Score</h4>

    <p style={{
      fontSize: "20px",
      fontWeight: "600"
    }}>
      {disciplineScore}/100
    </p>

    <small>
      Needs {needPercent}% | Wants {wantPercent}%
    </small>
  </div>

</div>

{/* SMART FINANCIAL HEALTH */}
<div
  style={{
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit,minmax(220px,1fr))",
    gap: "20px",
    marginTop: "20px"
  }}
>

  {/* HEALTH STATUS */}
  <div
    style={{
      background: darkMode ? "#111827" : "#ffffff",
      padding: "22px",
      borderRadius: "18px",
      boxShadow: darkMode
        ? "0 4px 20px rgba(0,0,0,0.4)"
        : "0 4px 20px rgba(0,0,0,0.08)"
    }}
  >
    <h4 style={{ marginBottom: "10px" }}>
      Financial Health
    </h4>

    <div
      style={{
        fontSize: "22px",
        fontWeight: "700",
        color:
          financialHealth === "Excellent"
            ? "#22c55e"
            : financialHealth === "Good"
            ? "#4f6df5"
            : financialHealth === "Average"
            ? "#f59e0b"
            : "#ef4444"
      }}
    >
      {financialHealth}
    </div>

    <small>
      Based on spending discipline
    </small>
  </div>

  {/* SAVINGS POTENTIAL */}
  <div
    style={{
      background: darkMode ? "#111827" : "#ffffff",
      padding: "22px",
      borderRadius: "18px",
      boxShadow: darkMode
        ? "0 4px 20px rgba(0,0,0,0.4)"
        : "0 4px 20px rgba(0,0,0,0.08)"
    }}
  >
    <h4 style={{ marginBottom: "10px" }}>
      Savings Potential
    </h4>

    <div
      style={{
        fontSize: "24px",
        fontWeight: "700",
        color: "#22c55e"
      }}
    >
      ₹{savingsPotential}
    </div>

    <small>
      Estimated reducible spending
    </small>
  </div>

  {/* RISK LEVEL */}
  <div
    style={{
      background: darkMode ? "#111827" : "#ffffff",
      padding: "22px",
      borderRadius: "18px",
      boxShadow: darkMode
        ? "0 4px 20px rgba(0,0,0,0.4)"
        : "0 4px 20px rgba(0,0,0,0.08)"
    }}
  >
    <h4 style={{ marginBottom: "10px" }}>
      Overspending Risk
    </h4>

    <div
      style={{
        fontSize: "22px",
        fontWeight: "700",
        color:
          riskLevel === "Low"
            ? "#22c55e"
            : riskLevel === "Medium"
            ? "#f59e0b"
            : "#ef4444"
      }}
    >
      {riskLevel}
    </div>

    <small>
      Based on alerts & wants ratio
    </small>
  </div>

  {/* SPENDING STYLE */}
  <div
    style={{
      background: darkMode ? "#111827" : "#ffffff",
      padding: "22px",
      borderRadius: "18px",
      boxShadow: darkMode
        ? "0 4px 20px rgba(0,0,0,0.4)"
        : "0 4px 20px rgba(0,0,0,0.08)"
    }}
  >
    <h4 style={{ marginBottom: "10px" }}>
      Spending Style
    </h4>

    <div
      style={{
        fontSize: "20px",
        fontWeight: "700",
        color: "#8b5cf6"
      }}
    >
      {spendingStyle}
    </div>

    <small>
      AI behavioral classification
    </small>
  </div>

  {/* DAILY BURN RATE */}
  <div
    style={{
      background: darkMode ? "#111827" : "#ffffff",
      padding: "22px",
      borderRadius: "18px",
      boxShadow: darkMode
        ? "0 4px 20px rgba(0,0,0,0.4)"
        : "0 4px 20px rgba(0,0,0,0.08)"
    }}
  >
    <h4 style={{ marginBottom: "10px" }}>
      Daily Burn Rate
    </h4>

    <div
      style={{
        fontSize: "24px",
        fontWeight: "700",
        color: "#ef4444"
      }}
    >
      ₹{dailyBurnRate}
    </div>

    <small>
      Average daily spending
    </small>
  </div>

</div>

      {/* AI SUMMARY */}
      <div className="card" style={{ marginTop: "20px" }}>
        <h3>AI Summary</h3>
        <p style={{ lineHeight: "1.7", fontSize: "14px" }}>{aiSummary}</p>
      </div>

      {/* CHARTS GRID */}
      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(300px,1fr))",
        gap: "20px",
        marginTop: "20px"
      }}>

        {/* PIE */}
        <div
  style={{
    background: darkMode ? "#111827" : "#ffffff",
    padding: "24px",
    borderRadius: "16px",
    boxShadow: darkMode
      ? "0 4px 20px rgba(0,0,0,0.4)"
      : "0 4px 20px rgba(0,0,0,0.08)"
  }}
>
  <h3 style={{ marginBottom: "16px" }}>Spending Breakdown</h3>

  <ResponsiveContainer width="100%" height={320}>
    <PieChart>
      
      {/* ✅ Gradient definitions */}
      <defs>
        <linearGradient id="grad1" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#4f6df5" />
          <stop offset="100%" stopColor="#6a85ff" />
        </linearGradient>

        <linearGradient id="grad2" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#22c55e" />
          <stop offset="100%" stopColor="#16a34a" />
        </linearGradient>

        <linearGradient id="grad3" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#f59e0b" />
          <stop offset="100%" stopColor="#d97706" />
        </linearGradient>

        <linearGradient id="grad4" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#ef4444" />
          <stop offset="100%" stopColor="#dc2626" />
        </linearGradient>
      </defs>

      <Pie
        data={data}
        dataKey="value"
        nameKey="name"
        cx="50%"
        cy="50%"
        innerRadius={70}   // donut style
        outerRadius={110}
        paddingAngle={3}
        cornerRadius={10}  // 🔥 rounded slices
      >
        {data.map((entry, index) => {
          const fills = [
            "url(#grad1)",
            "url(#grad2)",
            "url(#grad3)",
            "url(#grad4)"
          ];
          return <Cell key={index} fill={fills[index % fills.length]} />;
        })}
      </Pie>

      {/* ✅ CENTER LABEL */}
      <text
        x="50%"
        y="50%"
        textAnchor="middle"
        dominantBaseline="middle"
        style={{
          fontSize: "16px",
          fontWeight: "600",
          fill: darkMode ? "#e5e7eb" : "#111827"
        }}
      >
        ₹{data.reduce((sum, d) => sum + d.value, 0)}
      </text>

      {/* ✅ TOOLTIP */}
      <Tooltip
        contentStyle={{
          borderRadius: "10px",
          border: "none",
          background: darkMode ? "#1f2937" : "#fff",
          boxShadow: "0 4px 12px rgba(0,0,0,0.15)"
        }}
      />

      {/* ✅ LEGEND */}
      <Legend
        verticalAlign="bottom"
        height={36}
        iconType="circle"
      />

    </PieChart>
  </ResponsiveContainer>
</div>

        
        {/* BAR */}
<div
  style={{
    background: darkMode ? "#111827" : "#ffffff",
    padding: "24px",
    borderRadius: "16px",
    boxShadow: darkMode
      ? "0 4px 20px rgba(0,0,0,0.4)"
      : "0 4px 20px rgba(0,0,0,0.08)"
  }}
>
  <h3 style={{ marginBottom: "16px" }}>Category Comparison</h3>

  <ResponsiveContainer width="100%" height={300}>
    <BarChart data={categoryData}>
      
      {/* GRID */}
      <CartesianGrid
        strokeDasharray="3 3"
        stroke={darkMode ? "#374151" : "#e5e7eb"}
      />

      {/* X AXIS */}
      <XAxis
        dataKey="name"
        stroke={darkMode ? "#9ca3af" : "#6b7280"}
        tick={{ fontSize: 12 }}
      />

      {/* Y AXIS */}
      <YAxis
        stroke={darkMode ? "#9ca3af" : "#6b7280"}
        tick={{ fontSize: 12 }}
      />

      {/* TOOLTIP */}
      <Tooltip
        contentStyle={{
          borderRadius: "10px",
          border: "none",
          background: darkMode ? "#1f2937" : "#fff",
          boxShadow: "0 4px 12px rgba(0,0,0,0.15)"
        }}
      />

      {/* GRADIENT */}
      <defs>
        <linearGradient id="barGradient" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#4f6df5" />
          <stop offset="100%" stopColor="#6a85ff" />
        </linearGradient>
      </defs>

      {/* BAR */}
      <Bar
        dataKey="value"
        fill="url(#barGradient)"
        radius={[10, 10, 0, 0]}
        barSize={35}
      />
    </BarChart>
  </ResponsiveContainer>
</div>
</div>

{/* AI SPENDING BEHAVIOR PANEL */}
<div
  style={{
    marginTop: "24px",

    background: darkMode
      ? "linear-gradient(145deg,#0f172a,#111827)"
      : "#ffffff",

    borderRadius: "24px",

    padding: "30px",

    border: darkMode
      ? "1px solid rgba(255,255,255,0.06)"
      : "1px solid #e5e7eb",

    boxShadow: darkMode
      ? "0 10px 40px rgba(0,0,0,0.45)"
      : "0 10px 30px rgba(0,0,0,0.08)"
  }}
>

  {/* HEADER */}
  <div
    style={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      marginBottom: "30px",
      flexWrap: "wrap",
      gap: "14px"
    }}
  >

    <div>
      <h3
        style={{
          fontSize: "24px",
          fontWeight: "700",
          marginBottom: "6px"
        }}
      >
        Spending Behavior Intelligence
      </h3>

      <p
        style={{
          fontSize: "13px",
          color: darkMode ? "#94a3b8" : "#6b7280"
        }}
      >
        AI-powered analysis of your spending psychology
      </p>
    </div>

    {/* STATUS BADGE */}
    <div
      style={{
        padding: "10px 18px",
        borderRadius: "14px",

        background:
          wantPercent > 50
            ? "rgba(239,68,68,0.12)"
            : "rgba(34,197,94,0.12)",

        color:
          wantPercent > 50
            ? "#ef4444"
            : "#22c55e",

        fontWeight: "600",
        fontSize: "13px"
      }}
    >
      {wantPercent > 50
        ? "High Discretionary Spending"
        : "Healthy Financial Behavior"}
    </div>

  </div>

  {/* MAIN GRID */}
  <div
    style={{
      display: "grid",
      gridTemplateColumns:
        "repeat(auto-fit,minmax(320px,1fr))",
      gap: "30px",
      alignItems: "center"
    }}
  >

    {/* LEFT SIDE */}
    <div>

      <ResponsiveContainer
        width="100%"
        height={320}
      >
        <PieChart>

          {/* GLOW GRADIENTS */}
          <defs>

            <linearGradient
              id="needRing"
              x1="0"
              y1="0"
              x2="1"
              y2="1"
            >
              <stop
                offset="0%"
                stopColor="#22c55e"
              />
              <stop
                offset="100%"
                stopColor="#16a34a"
              />
            </linearGradient>

            <linearGradient
              id="wantRing"
              x1="0"
              y1="0"
              x2="1"
              y2="1"
            >
              <stop
                offset="0%"
                stopColor="#ef4444"
              />
              <stop
                offset="100%"
                stopColor="#dc2626"
              />
            </linearGradient>

          </defs>

          <Pie
            data={needWantData}
            dataKey="value"
            nameKey="name"

            innerRadius={85}
            outerRadius={120}

            paddingAngle={4}
            cornerRadius={12}
          >

            <Cell fill="url(#needRing)" />
            <Cell fill="url(#wantRing)" />

          </Pie>

          {/* CENTER TEXT */}
          <text
            x="50%"
            y="47%"
            textAnchor="middle"
            dominantBaseline="middle"
            style={{
              fontSize: "30px",
              fontWeight: "700",
              fill: darkMode
                ? "#ffffff"
                : "#111827"
            }}
          >
            {disciplineScore}
          </text>

          <text
            x="50%"
            y="58%"
            textAnchor="middle"
            dominantBaseline="middle"
            style={{
              fontSize: "13px",
              fill: darkMode
                ? "#94a3b8"
                : "#6b7280"
            }}
          >
            Financial Score
          </text>

          <Tooltip
  contentStyle={{
    background: darkMode
      ? "#0f172a"
      : "#ffffff",

    border: darkMode
      ? "1px solid rgba(255,255,255,0.08)"
      : "1px solid #e5e7eb",

    borderRadius: "14px",

    color: darkMode
      ? "#ffffff"
      : "#111827",

    fontSize: "14px",

    boxShadow:
      "0 10px 30px rgba(0,0,0,0.35)",

    padding: "12px"
  }}

  itemStyle={{
    color: darkMode
      ? "#ffffff"
      : "#111827",

    fontWeight: "600"
  }}

  labelStyle={{
    color: darkMode
      ? "#94a3b8"
      : "#6b7280",

    marginBottom: "6px"
  }}
/>

        </PieChart>
      </ResponsiveContainer>

    </div>

    {/* RIGHT SIDE */}
    <div>

      {/* METRICS */}
      <div
        style={{
          display: "grid",
          gap: "16px"
        }}
      >

        {/* NEEDS */}
        <div
          style={{
            padding: "18px",
            borderRadius: "18px",

            background: darkMode
              ? "#1e293b"
              : "#f8fafc"
          }}
        >
          <div
            style={{
              fontSize: "13px",
              color: "#94a3b8"
            }}
          >
            Essential Spending
          </div>

          <div
            style={{
              marginTop: "6px",
              fontSize: "28px",
              fontWeight: "700",
              color: "#22c55e"
            }}
          >
            {needPercent}%
          </div>

          <div
            style={{
              marginTop: "4px",
              fontSize: "13px"
            }}
          >
            ₹{needWantTotals.Need}
          </div>
        </div>

        {/* WANTS */}
        <div
          style={{
            padding: "18px",
            borderRadius: "18px",

            background: darkMode
              ? "#1e293b"
              : "#f8fafc"
          }}
        >
          <div
            style={{
              fontSize: "13px",
              color: "#94a3b8"
            }}
          >
            Discretionary Spending
          </div>

          <div
            style={{
              marginTop: "6px",
              fontSize: "28px",
              fontWeight: "700",
              color: "#ef4444"
            }}
          >
            {wantPercent}%
          </div>

          <div
            style={{
              marginTop: "4px",
              fontSize: "13px"
            }}
          >
            ₹{needWantTotals.Want}
          </div>
        </div>

      </div>

      {/* AI ANALYSIS */}
      <div
        style={{
          marginTop: "24px",

          padding: "18px",

          borderRadius: "18px",

          background: darkMode
            ? "rgba(79,109,245,0.12)"
            : "#eef2ff",

          border: "1px solid rgba(79,109,245,0.15)"
        }}
      >

        <div
          style={{
            fontWeight: "700",
            marginBottom: "10px"
          }}
        >
          AI Behavioral Insight
        </div>

        <div
          style={{
            fontSize: "14px",
            lineHeight: "1.8",
            color: darkMode
              ? "#d1d5db"
              : "#374151"
          }}
        >

          {wantPercent > 60 &&
            "Your spending pattern indicates impulsive discretionary behavior. Reducing non-essential purchases can significantly improve long-term savings."}

          {wantPercent <= 60 &&
            wantPercent > 35 &&
            "Your spending behavior is moderately balanced. Some discretionary expenses are present but remain within manageable levels."}

          {wantPercent <= 35 &&
            "Excellent financial discipline detected. Most of your spending is focused on essential categories, indicating strong budgeting habits."}

        </div>

      </div>

    </div>

  </div>

</div>

{/* PREMIUM MONTHLY TREND */}
<div
  style={{
    background: darkMode
      ? "linear-gradient(145deg,#0f172a,#111827)"
      : "#ffffff",

    padding: "28px",
    borderRadius: "24px",
    marginTop: "24px",

    border: darkMode
      ? "1px solid rgba(255,255,255,0.06)"
      : "1px solid #e5e7eb",

    boxShadow: darkMode
      ? "0 10px 40px rgba(0,0,0,0.45)"
      : "0 10px 30px rgba(0,0,0,0.08)"
  }}
>

  {/* HEADER */}
  <div
    style={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      marginBottom: "24px"
    }}
  >

    <div>
      <h3
        style={{
          fontSize: "22px",
          fontWeight: "700",
          marginBottom: "6px"
        }}
      >
        Monthly Spending Trend
      </h3>

      <p
        style={{
          fontSize: "13px",
          color: darkMode ? "#94a3b8" : "#6b7280"
        }}
      >
        Smart tracking of Need vs Want expenses
      </p>
    </div>

    {/* MINI ANALYTICS BADGE */}
    <div
      style={{
        padding: "10px 16px",
        borderRadius: "14px",

        background:
          wantPercent > 50
            ? "rgba(239,68,68,0.12)"
            : "rgba(34,197,94,0.12)",

        color:
          wantPercent > 50
            ? "#ef4444"
            : "#22c55e",

        fontWeight: "600",
        fontSize: "13px"
      }}
    >
      {wantPercent > 50
        ? "High Want Spending"
        : "Healthy Spending"}
    </div>
  </div>

  {/* CHART */}
  <ResponsiveContainer width="100%" height={380}>
    <BarChart
      data={monthlyNeedWantData}
      barGap={8}
    >

      {/* GRADIENTS */}
      <defs>

        <linearGradient
          id="needGradient"
          x1="0"
          y1="0"
          x2="0"
          y2="1"
        >
          <stop
            offset="0%"
            stopColor="#22c55e"
          />
          <stop
            offset="100%"
            stopColor="#16a34a"
          />
        </linearGradient>

        <linearGradient
          id="wantGradient"
          x1="0"
          y1="0"
          x2="0"
          y2="1"
        >
          <stop
            offset="0%"
            stopColor="#ef4444"
          />
          <stop
            offset="100%"
            stopColor="#dc2626"
          />
        </linearGradient>

      </defs>

      {/* GRID */}
      <CartesianGrid
        strokeDasharray="4 4"
        vertical={false}
        stroke={
          darkMode
            ? "rgba(255,255,255,0.08)"
            : "#e5e7eb"
        }
      />

      {/* X AXIS */}
      <XAxis
        dataKey="month"
        tick={{
          fill: darkMode
            ? "#94a3b8"
            : "#6b7280",
          fontSize: 12
        }}
        axisLine={false}
        tickLine={false}
      />

      {/* Y AXIS */}
      <YAxis
        tick={{
          fill: darkMode
            ? "#94a3b8"
            : "#6b7280",
          fontSize: 12
        }}
        axisLine={false}
        tickLine={false}
      />

      {/* TOOLTIP */}
      <Tooltip
        cursor={{
          fill: "rgba(255,255,255,0.03)"
        }}

        contentStyle={{
          borderRadius: "16px",
          border: "none",

          background: darkMode
            ? "#111827"
            : "#ffffff",

          boxShadow:
            "0 10px 30px rgba(0,0,0,0.25)",

          padding: "12px"
        }}
      />

      {/* LEGEND */}
      <Legend
        wrapperStyle={{
          paddingTop: "18px"
        }}
      />

      {/* NEED BAR */}
      <Bar
        dataKey="Need"
        fill="url(#needGradient)"
        radius={[12, 12, 0, 0]}
        barSize={24}
      />

      {/* WANT BAR */}
      <Bar
        dataKey="Want"
        fill="url(#wantGradient)"
        radius={[12, 12, 0, 0]}
        barSize={24}
      />

    </BarChart>
  </ResponsiveContainer>

  {/* SMART FOOTER */}
  <div
    style={{
      marginTop: "18px",

      display: "flex",
      justifyContent: "space-between",

      flexWrap: "wrap",
      gap: "14px"
    }}
  >

    <div
      style={{
        padding: "14px",
        borderRadius: "14px",

        background: darkMode
          ? "#1e293b"
          : "#f8fafc",

        flex: 1
      }}
    >
      <div
        style={{
          fontSize: "12px",
          color: "#94a3b8"
        }}
      >
        Total Needs
      </div>

      <div
        style={{
          marginTop: "4px",
          fontSize: "20px",
          fontWeight: "700",
          color: "#22c55e"
        }}
      >
        ₹{needWantTotals.Need}
      </div>
    </div>

    <div
      style={{
        padding: "14px",
        borderRadius: "14px",

        background: darkMode
          ? "#1e293b"
          : "#f8fafc",

        flex: 1
      }}
    >
      <div
        style={{
          fontSize: "12px",
          color: "#94a3b8"
        }}
      >
        Total Wants
      </div>

      <div
        style={{
          marginTop: "4px",
          fontSize: "20px",
          fontWeight: "700",
          color: "#ef4444"
        }}
      >
        ₹{needWantTotals.Want}
      </div>
    </div>

  </div>

</div>

      {/* INSIGHTS LIST */}
      <div className="card" style={{ marginTop: "20px" }}>
        <h3>Detailed Insights</h3>
        <div style={{ marginBottom: "15px" }}>

  {needPercent >= 70 && (
    <p>
      ✅ Excellent financial discipline detected.
    </p>
  )}

  {wantPercent >= 50 && (
    <p>
      ⚠️ High discretionary spending detected.
    </p>
  )}

  {disciplineScore < 60 && (
    <p>
      🚨 Your financial discipline score is low.
    </p>
  )}

  {disciplineScore >= 80 && (
    <p>
      💡 Your spending behavior appears balanced.
    </p>
  )}

</div>

        {insights.length > 0 ? (
          insights.map((i, idx) => (
            <div
              key={idx}
              style={{
                padding: "10px",
                borderRadius: "8px",
                marginBottom: "8px",
                background: darkMode ? "#1f2937" : "#f9fafb"
              }}
            >
              {i}
            </div>
          ))
        ) : (
          <p>No insights available</p>
        )}
      </div>

    </div>
  );
}

export default InsightsPage;
